sys_script.script:
(function executeRule(current, previous) {
    if (current.getValue('state') == 'cancelled' || current.getValue('state') == 'closed') {
        return;
    }
    var car = current.getValue('car');
    var s = current.getValue('start_date');
    var e = current.getValue('end_date');
    if (!car || !s || !e) {
        return;
    }
    var u = new GlideRecord('x_2203703_car_re_0_car_unavail');
    u.addQuery('car', car);
    u.addQuery('start_date', '<=', e);
    u.addQuery('end_date', '>=', s);
    u.query();
    if (u.next()) {
        gs.addErrorMessage('This car is out of service from ' + u.getValue('start_date') + ' to ' + u.getValue('end_date') + '. Please pick another car or other dates.');
        current.setAbortAction(true);
    }
})(current, previous);
